INSERT INTO `alumni_events` (`id`, `title`, `event_for`, `session_id`, `class_id`, `section`, `from_date`, `to_date`, `note`, `photo`, `is_active`, `event_notification_message`, `show_onwebsite`, `created_at`) VALUES (1, 'Independence Day Celebration !!!!!!', 'all', NULL, NULL, 'null', '2023-08-15 00:00:00', '2023-08-15 23:59:00', '', NULL, 0, 'It is a proud moment for everyone as we approach another Independence Day on August 15th. This annual observance has a great significance and this special day is celebrated for commemorating our brave leaders and fighters of history who won us the freedom we are enjoying today.', 0, '2023-08-24 08:59:57');
INSERT INTO `alumni_events` (`id`, `title`, `event_for`, `session_id`, `class_id`, `section`, `from_date`, `to_date`, `note`, `photo`, `is_active`, `event_notification_message`, `show_onwebsite`, `created_at`) VALUES (2, 'Admission Camp', 'all', NULL, NULL, 'null', '2023-07-01 00:00:00', '2023-07-20 23:59:00', '', NULL, 0, 'Admission camp is an online education website that delivers timely blogs related to the field of education. We also deliver general education related.', 0, '2023-08-24 09:00:42');
INSERT INTO `alumni_events` (`id`, `title`, `event_for`, `session_id`, `class_id`, `section`, `from_date`, `to_date`, `note`, `photo`, `is_active`, `event_notification_message`, `show_onwebsite`, `created_at`) VALUES (3, 'Summer Vacation', 'all', NULL, NULL, 'null', '2023-06-05 00:00:00', '2023-06-12 23:59:00', 'Summer vacation is the best time of the year as it gives me a chance to relax and explore new things. It gives me an opportunity to take a break from my daily study routine and adopt new hobbies like gardening, dancing and painting, while also having fun with friends.', NULL, 0, 'Summer vacation is the best time of the year as it gives me a chance to relax and explore new things. It gives me an opportunity to take a break from my daily study routine and adopt new hobbies like gardening, dancing and painting, while also having fun with friends.', 0, '2023-08-24 09:01:23');
