) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: cbse_template_terms
#

DROP TABLE IF EXISTS `cbse_template_terms`;

CREATE TABLE `cbse_template_terms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
