  `updated_at` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: internalresulttable
#

DROP TABLE IF EXISTS `internalresulttable`;

CREATE TABLE `internalresulttable` (
