  KEY `subjectid` (`subjectid`),
  KEY `session_id` (`session_id`),
  KEY `stid` (`stid`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: item
#

DROP TABLE IF EXISTS `item`;

CREATE TABLE `item` (
